package com.greenocean.backend.wellbeing.service;

import com.greenocean.backend.catalog.service.GrowthLibrary;
import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Service @Transactional
public class GrowthRewards {
 private final JdbcTemplate db;private final GrowthLibrary library;private final boolean enabled;private final int version,lesson,exercise,course;
 public GrowthRewards(JdbcTemplate db,GrowthLibrary library,@Value("${greenocean.education.rewards-enabled:false}")boolean enabled,@Value("${greenocean.education.reward-rule-version:1}")int version,@Value("${greenocean.education.lesson-points:10}")int lesson,@Value("${greenocean.education.exercise-points:5}")int exercise,@Value("${greenocean.education.course-points:30}")int course){this.db=db;this.library=library;this.enabled=enabled;this.version=version;this.lesson=lesson;this.exercise=exercise;this.course=course;}
 private void lock(UUID user){db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","growth-rewards:"+user);}
 private void require(UUID user){library.actor(user);if(!enabled)throw new com.greenocean.backend.listener.live.LiveSupportException(503,"REWARDS_DISABLED","Private learning rewards await release approval.");}
 private void rule(){if(version<1||lesson<0||exercise<0||course<0||Math.max(lesson,Math.max(exercise,course))>1000)throw new IllegalStateException("Invalid reward policy configuration");db.update("INSERT INTO growth_reward_rules(version,lesson_points,exercise_points,course_points) VALUES(?,?,?,?) ON CONFLICT DO NOTHING",version,lesson,exercise,course);var r=db.queryForMap("SELECT * FROM growth_reward_rules WHERE version=?",version);if(((Number)r.get("lesson_points")).intValue()!=lesson||((Number)r.get("exercise_points")).intValue()!=exercise||((Number)r.get("course_points")).intValue()!=course)throw new IllegalStateException("Changed reward amounts require a new policy version");}
 @EventListener public void completed(LearningCourses.LearningEvent event){if(!enabled)return;require(event.owner());lock(event.owner());rule();award(event.owner(),event.type(),event.completion());db.queryForList("SELECT growth_refresh_badges(?)",event.owner());}
 private void award(UUID user,String type,UUID completion){db.update("INSERT INTO growth_reward_ledger(owner_id,source_type,completion_id,course_key,activity_key,rule_version,point_delta) SELECT ?,?,?,s.course_key,s.activity_key,r.version,CASE ? WHEN 'LESSON' THEN r.lesson_points WHEN 'EXERCISE' THEN r.exercise_points ELSE r.course_points END FROM growth_reward_source(?,?,?) s JOIN growth_reward_rules r ON r.version=? WHERE growth_resource_available(s.course_id) AND EXISTS(SELECT 1 FROM growth_resources WHERE id=s.course_id AND published_revision=s.revision) ON CONFLICT DO NOTHING",user,type,completion,type,type,completion,user,version);}
 public Map<String,Object> dashboard(UUID user,int page){require(user);if(page<0||page>100000)throw new IllegalArgumentException("Invalid reward history page");return Map.of("balance",db.queryForObject("SELECT COALESCE(sum(point_delta),0) FROM growth_reward_ledger WHERE owner_id=?",Long.class,user),"milestones",db.queryForList("SELECT source_type,count(*) AS count FROM growth_reward_ledger e WHERE owner_id=? AND reversal_of IS NULL AND NOT EXISTS(SELECT 1 FROM growth_reward_ledger r WHERE r.reversal_of=e.id) GROUP BY source_type",user),"badges",db.queryForList("SELECT code,earned_at,revoked_at FROM growth_learning_badges WHERE owner_id=? ORDER BY earned_at,code",user),"events",db.queryForList("SELECT id,source_type,completion_id,rule_version,point_delta,reversal_of,created_at FROM growth_reward_ledger WHERE owner_id=? ORDER BY created_at DESC,id DESC LIMIT 20 OFFSET ?",user,(long)page*20),"currentCourses",db.queryForList("SELECT DISTINCT r.id,v.document->>'title' AS title,learning_progress(?,r.id,r.published_revision) AS percent FROM learning_lesson_views opening JOIN growth_resources r ON r.id=opening.course_id JOIN growth_resource_versions v ON v.resource_id=r.id AND v.revision=r.published_revision WHERE opening.owner_id=? AND growth_resource_available(r.id) ORDER BY r.id LIMIT 10",user,user),"page",page,"scope","Private educational milestones only. Not a health score, credential, cash balance or support priority.");}
 public void reverse(UUID actor,UUID event,String reason){library.admin(actor);reason(reason);var rows=db.queryForList("SELECT owner_id FROM growth_reward_ledger WHERE id=? AND reversal_of IS NULL",event);if(rows.isEmpty())throw new NotFoundException("Reward event was not found");UUID owner=(UUID)rows.getFirst().get("owner_id");db.queryForList("SELECT id FROM users WHERE id=? FOR SHARE",owner);lock(owner);db.update("INSERT INTO growth_reward_ledger(owner_id,source_type,completion_id,course_key,activity_key,rule_version,point_delta,reversal_of,actor_id,reason) SELECT owner_id,source_type,completion_id,course_key,activity_key,rule_version,-point_delta,id,?,? FROM growth_reward_ledger WHERE id=? AND reversal_of IS NULL ON CONFLICT DO NOTHING",actor,reason,event);db.queryForList("SELECT growth_refresh_badges(?)",owner);audit(actor,owner,"GROWTH_REWARD_REVERSED",reason);}
 public void reconcile(UUID actor,UUID owner,String reason){library.admin(actor);reason(reason);require(owner);lock(owner);rule();for(String type:List.of("LESSON","EXERCISE","COURSE")){String table=type.equals("LESSON")?"learning_lesson_completions":type.equals("EXERCISE")?"learning_exercise_completions":"learning_course_completions";for(UUID id:db.queryForList("SELECT id FROM "+table+" c WHERE owner_id=? AND growth_resource_available(course_id) AND course_revision=(SELECT published_revision FROM growth_resources WHERE id=course_id) AND NOT EXISTS(SELECT 1 FROM growth_reward_ledger e WHERE e.owner_id=c.owner_id AND e.source_type=? AND e.course_key=c.source_course_key AND e.activity_key="+(type.equals("COURSE")?"c.source_course_key":"c.lesson_key")+" AND e.reversal_of IS NULL) ORDER BY completed_at,id LIMIT 200",UUID.class,owner,type))award(owner,type,id);}db.queryForList("SELECT growth_refresh_badges(?)",owner);audit(actor,owner,"GROWTH_REWARD_RECONCILED",reason);}
 private void reason(String reason){if(reason==null||reason.trim().length()<10||reason.length()>1000)throw new IllegalArgumentException("A specific correction/reconciliation reason is required");}
 private void audit(UUID actor,UUID owner,String action,String reason){db.update("INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,metadata) VALUES(?,?,'PRIVATE_LEARNING_REWARD',?,jsonb_build_object('reason',?::text))",actor,action,owner,reason);}
}
